try:
    n = int(input())
    dung = n > 1
    i = 2
    while dung and i * i <= n:
        dung = n % i != 0
        i += 1
    print("YES" if dung else "NO")
except ValueError:
    print("NO")

def main():
    def gt(k):
        return 1 if k < 2 else k * gt(k - 1)
    n = int(input())
    print(gt(n))

